{"check_id": "CHECK-W5-PROP-W1-EIP7934-INV-002-INTERNAL", "checklist_item": {"id": "CHECK-W5-PROP-W1-EIP7934-INV-002-INTERNAL", "property_id": "PROP-W1-EIP7934-INV-002", "graph_element_under_test": "STATE-CONSENSUS-LAYER-PROTECTED", "title": "Falsify 2 MiB safety margin between MAX_RLP_BLOCK_SIZE and CL MAX_BLOCK_SIZE", "reachability": {"classification": "internal-only", "entry_points": ["Internal API"], "attacker_controlled": false, "bug_bounty_scope": "in-scope"}, "bug_class": "Resource Exhaustion", "risk_category": "Block Validation", "severity_hint": "MEDIUM", "detection_procedure": "1. Construct an EL block that is exactly MAX_RLP_BLOCK_SIZE (8 MiB) in serialized RLP form. 2. Wrap this EL block in a beacon block (SignedBeaconBlock) with maximum-size attestations, sync committee, and blob KZG commitments. 3. Measure the total serialized size of the beacon block. 4. Verify total size < MAX_BLOCK_SIZE (10 MiB). 5. The difference must be >= 2 MiB to maintain the safety margin. 6. Edge case: maximum number of blob_kzg_commitments (max_blobs_per_block) combined with maximum EL block size.", "executable_checks": ["Construct max-size EL block (8 MiB RLP), wrap in beacon block, verify total < 10 MiB", "Compute worst-case beacon block wrapper overhead with max blob commitments", "Verify 2 MiB margin holds under all parameter combinations"], "notes": "Source: PROP-W1-EIP7934-INV-002. Invariant falsification. Related ambiguity: AMB-EIP7934-02, assumption: ASSUM-EIP7934-01. If safety margin is insufficient, valid EL blocks get rejected at CL."}, "checklist_file": "outputs/02_CHECKLIST_PARTIAL_W5_1770089239_1.json", "property_id": "PROP-W1-EIP7934-INV-002", "subgraph_id": "SUBGRAPH-EIP7934-SECURITY", "subgraph_file": "outputs/01b_SUBGRAPHS/spec_c320ad257dd3b47154ed04e23bb85da3e4eacaec.json", "subgraph": {"id": "SUBGRAPH-EIP7934-SECURITY", "aspect": "security_boundary", "title": "EIP-7934: Protection Against Oversized Block Attacks", "description": "Models the security boundary where size limits protect against DoS attacks using oversized blocks", "nodes": [{"id": "STATE-ATTACKER-CRAFTED-BLOCK", "label": "Attacker Crafts Oversized Block", "type": "State", "description": "Malicious actor has constructed a block exceeding normal size expectations"}, {"id": "ACTION-RECEIVE-MALICIOUS-BLOCK", "label": "Receive Potentially Malicious Block", "type": "Action", "description": "Node receives block data from untrusted peer"}, {"id": "ACTION-EARLY-SIZE-CHECK", "label": "Perform Early Size Check", "type": "Action", "description": "Check block size before performing expensive validation operations"}, {"id": "STATE-ATTACK-MITIGATED", "label": "Oversized Block Attack Mitigated", "type": "State", "description": "Attack was prevented by size validation before resource exhaustion"}, {"id": "STATE-CONSENSUS-LAYER-PROTECTED", "label": "Consensus Layer Protected", "type": "State", "description": "2 MiB safety margin ensures consensus layer constraints are not violated"}], "edges": [{"id": "EDGE-ATTACKER-SENDS", "source": "EXT-MALICIOUS-PEER", "target": "ACTION-RECEIVE-MALICIOUS-BLOCK", "label": "Attacker sends oversized block via P2P", "data_involved": ["DATA-OVERSIZED-BLOCK"]}, {"id": "EDGE-APPLY-SIZE-CHECK", "source": "ACTION-RECEIVE-MALICIOUS-BLOCK", "target": "ACTION-EARLY-SIZE-CHECK", "label": "Apply size validation first"}, {"id": "EDGE-BLOCK-REJECTED-EARLY", "source": "ACTION-EARLY-SIZE-CHECK", "target": "STATE-ATTACK-MITIGATED", "label": "Block rejected before expensive processing"}, {"id": "EDGE-SAFETY-MARGIN", "source": "STATE-ATTACK-MITIGATED", "target": "STATE-CONSENSUS-LAYER-PROTECTED", "label": "2 MiB margin prevents CL constraint violation"}], "external_entities": [{"id": "EXT-MALICIOUS-PEER", "name": "Malicious Peer", "description": "Attacker node attempting to propagate oversized blocks to cause resource exhaustion"}]}}
{"check_id": "CHECK-W5-PROP-W1-EIP8070-INV-001-INTERNAL", "checklist_item": {"id": "CHECK-W5-PROP-W1-EIP8070-INV-001-INTERNAL", "property_id": "PROP-W1-EIP8070-INV-001", "graph_element_under_test": "ACTION-PROBABILISTIC-ROLE-DECISION", "title": "Falsify independence and unpredictability of transaction role assignment PRNG", "reachability": {"classification": "external-reachable", "entry_points": ["P2P"], "attacker_controlled": true, "bug_bounty_scope": "in-scope"}, "bug_class": "Weak Randomness", "risk_category": "P2P Network", "severity_hint": "MEDIUM", "detection_procedure": "1. Observe a node's role decisions (provider vs sampler) for a sequence of transaction announcements from the same peer. 2. Perform statistical tests: (a) chi-squared test for uniform distribution, (b) serial correlation test for sequential dependence, (c) runs test for randomness. 3. Attempt to predict future role decisions based on observed history (if PRNG is seeded with predictable inputs like peer_id or tx_hash). 4. Check if the announcing peer can influence the seed (e.g., by choosing specific tx hashes). 5. Verify the PRNG source is cryptographically secure (not math/rand or similar).", "executable_checks": ["Collect 1000+ role decisions, run chi-squared test for uniformity", "Attempt prediction of next role decision from observed sequence", "Audit PRNG source: verify CSPRNG usage, not deterministic seed from peer-controlled data"], "notes": "Source: PROP-W1-EIP8070-INV-001. Invariant falsification. Related ambiguity: AMB-EIP8070-01. If role is predictable, attacker can target providers to suppress data availability."}, "checklist_file": "outputs/02_CHECKLIST_PARTIAL_W5_1770089239_1.json", "property_id": "PROP-W1-EIP8070-INV-001", "subgraph_id": "SUBGRAPH-EIP8070-TX-LIFECYCLE", "subgraph_file": "outputs/01b_SUBGRAPHS/spec_fdbbaecb83dd8fe9bab44d1328fa6e2f3713d5af.json", "subgraph": {"id": "SUBGRAPH-EIP8070-TX-LIFECYCLE", "aspect": "transaction_lifecycle", "title": "EIP-8070: Sparse Blob