CUTE-PAIRING-CHECK", "label": "Execute BLS Pairing Check", "type": "Action", "description": "Verify pairing equation: e(LL, [s^n]) == e(RL, [1]) using KZG_SETUP_G2_MONOMIAL[FIELD_ELEMENTS_PER_CELL]", "precondition": [], "postcondition": ["STATE-BATCH-VERIFIED"]}, {"id": "STATE-BATCH-VERIFIED", "label": "Batch Verification Result", "type": "State", "description": "Pairing check returns true (all cells valid) or false (at least one cell invalid)"}], "edges": [{"id": "EDGE-VERIFIER-INPUT", "source": "EXT-CELL-PROVIDER", "target": "STATE-CELLS-RECEIVED-FOR-VERIFY", "label": "Cells, proofs, commitments submitted for verification", "data_involved": ["DATA-COMMITMENTS-BYTES", "DATA-CELL-INDICES", "DATA-CELLS", "DATA-PROOFS-BYTES"]}, {"id": "EDGE-VALIDATE-INPUTS", "source": "STATE-CELLS-RECEIVED-FOR-VERIFY", "target": "ACTION-VALIDATE-BATCH-INPUTS", "label": "Begin input validation", "data_involved": ["proof", "kzg_commitment", "cell"]}, {"id": "EDGE-DESERIALIZE", "source": "ACTION-VALIDATE-BATCH-INPUTS", "target": "ACTION-DESERIALIZE-COMMITMENTS-PROOFS", "label": "Inputs valid, deserialize BLS elements", "data_involved": ["proof", "kzg_commitment", "cell"]}, {"id": "EDGE-CONVERT-CELLS", "source": "ACTION-DESERIALIZE-COMMITMENTS-PROOFS", "target": "ACTION-CONVERT-CELLS-TO-COSET-EVALS", "label": "Convert cell bytes to field elements", "data_involved": ["cell"]}, {"id": "EDGE-FIAT-SHAMIR", "source": "ACTION-CONVERT-CELLS-TO-COSET-EVALS", "target": "ACTION-COMPUTE-FIAT-SHAMIR-CHALLENGE", "label": "Compute deterministic random challenge from all inputs", "data_involved": ["hash", "blob", "cell"]}, {"id": "EDGE-PAIRING-ARGS", "source": "ACTION-COMPUTE-FIAT-SHAMIR-CHALLENGE", "target": "ACTION-COMPUTE-PAIRING-ARGUMENTS", "label": "Use challenge r to build linear combination for pairing", "data_involved": ["hash", "kzg_commitment", "blob", "cell"]}, {"id": "EDGE-PAIRING", "source": "ACTION-COMPUTE-PAIRING-ARGUMENTS", "target": "ACTION-EXECUTE-PAIRING-CHECK", "label": "Execute fina