{"check_id": "CHECK-W6-PROP-W1-DASCORE-INV-003-INTERNAL", "checklist_item": {"id": "CHECK-W6-PROP-W1-DASCORE-INV-003-INTERNAL", "property_id": "PROP-W1-DASCORE-INV-003", "graph_element_under_test": "ACTION-COMPUTE-COLUMNS-FOR-GROUPS", "title": "Falsify column mapping uniqueness: verify NUMBER_OF_CUSTODY_GROUPS * i + custody_group produces no overlaps", "reachability": {"classification": "internal-only", "entry_points": ["Internal API"], "attacker_controlled": false, "validation_layers": [], "bug_bounty_scope": "in-scope"}, "bug_class": "Data Availability Failure / Incorrect Column Assignment", "risk_category": "Consensus Layer - PeerDAS Column Mapping", "severity_hint": "CRITICAL", "detection_procedure": "1. For all valid custody_group values [0, NUMBER_OF_CUSTODY_GROUPS) and all valid i values [0, columns_per_group): compute column_index = NUMBER_OF_CUSTODY_GROUPS * i + custody_group. 2. Collect all column indices into a set. Verify set size equals total expected columns (NUMBER_OF_COLUMNS). 3. Verify no duplicates exist. 4. Verify all column indices are in range [0, NUMBER_OF_COLUMNS). 5. Test with actual Fulu config values: NUMBER_OF_CUSTODY_GROUPS=128, NUMBER_OF_COLUMNS=128. 6. Verify each custody group maps to exactly the expected number of columns.", "executable_checks": ["Assert all generated column indices are unique (set size == expected total)", "Assert all column indices in [0, NUMBER_OF_COLUMNS)", "Assert each custody group maps to exactly NUMBER_OF_COLUMNS / NUMBER_OF_CUSTODY_GROUPS columns", "Assert complete coverage: union of all custody group columns == all columns"], "notes": "Source: PROP-W1-DASCORE-INV-003. Invariant type. Critical: incorrect column mapping across all nodes would cause systematic data availability failures for the entire network."}, "checklist_file": "outputs/02_CHECKLIST_PARTIAL_W6_1770089239_1.json", "property_id": "PROP-W1-DASCORE-INV-003", "subgraph_id": "SUBGRAPH-DAS-CORE-CUSTODY-ASSIGNMENT", "subgraph_file": "outputs/01b_SUBGRAPHS/spec_170b68e3c9a7_1770079940_1.json", "subgraph": {"id": "SUBGRAPH-DAS-CORE-CUSTODY-ASSIGNMENT", "aspect": "networking", "title": "DAS Core: Custody Group Assignment and Column Distribution", "description": "Models how nodes are deterministically assigned custody groups and corresponding columns, including subnet joining and data availability obligations", "nodes": [{"id": "STATE-NODE-UNASSIGNED", "label": "Node Without Custody Assignment", "type": "State", "description": "A node has joined the network but has not yet computed its custody group assignments"}, {"id": "ACTION-COMPUTE-CUSTODY-GROUPS", "label": "Compute Custody Groups via get_custody_groups", "type": "Action", "description": "Deterministically compute custody group indices from node_id using pseudo-random selection with iteration, ensuring at least CUSTODY_REQUIREMENT (4) groups", "precondition": ["STATE-NODE-UNASSIGNED"], "postcondition": ["STATE-CUSTODY-GROUPS-ASSIGNED"]}, {"id": "STATE-CUSTODY-GROUPS-ASSIGNED", "label": "Custody Groups Assigned", "type": "State", "description": "Node has computed its set of custody group indices (minimum 4, up to custody_group_count advertised in ENR)"}, {"id": "ACTION-COMPUTE-COLUMNS-FOR-GROUPS", "label": "Compute Columns for Custody Groups", "type": "Action", "description": "Map each custody group to column indices using formula: NUMBER_OF_CUSTODY_GROUPS * i + custody_group, yielding specific columns the node must custody", "precondition": ["STATE-CUSTODY-GROUPS-ASSIGNED"], "postcondition": ["STATE-COLUMNS-DETERMINED"]}, {"id": "STATE-COLUMNS-DETERMINED", "label": "Custody Columns Determined", "type": "State", "description": "Node knows which of the 128 columns it is responsible for storing and serving"}, {"id": "ACTION-JOIN-SUBNETS", "label": "Join Gossip Subnets for Custody Groups", "type": "Action", "description": "Node subscribes to gossip subnets corresponding to its assigned custody groups to receive column data", "precondition": ["STATE-COLUMNS-DETERMINED"], "postcondition": ["STATE-SUBSCRIBED-TO-SUBNETS"]}, {"id": "STATE-SUBSCRIBED-TO-SUBNETS", "label": "Subscribed to Column Subnets", "type": "State", "description": "Node is actively receiving column gossip on subnets for its custody groups"}], "edges": [{"id": "EDGE-START-ASSIGNMENT", "source": "STATE-NODE-UNASSIGNED", "target": "ACTION-COMPUTE-CUSTODY-GROUPS", "label": "Node initializes custody assignment", "data_involved": ["custody_group"]}, {"id": "EDGE-GROUPS-COMPUTED", "source": "ACTION-COMPUTE-CUSTODY-GROUPS", "target": "STATE-CUSTODY-GROUPS-ASSIGNED", "label": "Custody groups computed from node_id", "data_involved": ["DATA-NODE-ID", "DATA-CUSTODY-GROUP-COUNT"]}, {"id": "EDGE-MAP-TO-COLUMNS", "source": "STATE-CUSTODY-GROUPS-ASSIGNED", "target": "ACTION-COMPUTE-COLUMNS-FOR-GROUPS", "label": "Map groups to columns", "data_involved": ["column", "custody_group"]}, {"id": "EDGE-COLUMNS-COMPUTED", "source": "ACTION-COMPUTE-COLUMNS-FOR-GROUPS", "target": "STATE-COLUMNS-DETERMINED", "label": "Column indices computed via NUMBER_OF_CUSTODY_GROUPS * i + custody_group", "data_involved": ["column", "custody_group"]}, {"id": "EDGE-JOIN-SUBNETS", "source": "STATE-COLUMNS-DETERMINED", "target": "ACTION-JOIN-SUBNETS", "label": "Subscribe to corresponding subnets", "data_involved": ["gossip_message", "column", "custody_group"]}, {"id": "EDGE-SUBNETS-JOINED", "source": "ACTION-JOIN-SUBNETS", "target": "STATE-SUBSCRIBED-TO-SUBNETS", "label": "Gossip subscriptions active", "data_involved": ["gossip_message", "column", "custody_group"]}], "external_entities": [{"id": "EXT-NETWORK-PEERS", "name": "Network Peers", "description": "Other nodes that can verify custody obligations using the deterministic public assignment function and request columns via Req/Resp"}, {"id": "EXT-PEER-NODE", "name": "Peer Node", "description": "Any peer that can verify a node's custody obligations using the public deterministic assignment function"}]}}
