"ACTION-EXPOSE-RECONSTRUCTED", "label": "Make recovered columns accessible", "data_involved": ["data_column_sidecar"]}, {"id": "EDGE-REGOSSIP", "source": "STATE-FULL-MATRIX-RECOVERED", "target": "ACTION-REGOSSIP-COLUMNS", "label": "Re-gossip on subscribed subnets", "data_involved": ["gossip_message"]}, {"id": "EDGE-DISTRIBUTED", "source": "ACTION-REGOSSIP-COLUMNS", "target": "STATE-COLUMNS-DISTRIBUTED", "label": "Columns cross-seeded to peers", "data_involved": ["gossip_message", "column"]}], "external_entities": [{"id": "EXT-SUBNET-PEERS", "name": "Subnet Peers", "description": "Peers on subnets the node is subscribed to, who receive re-gossiped reconstructed columns"}]}}
